/* Model creation/destruction functions */

void MODEL_mkTbNocRouter::create_model(tSimStateHdl simHdl, bool master)
{
  sim_hdl = simHdl;
  init_reset_request_counters(sim_hdl);
  mkTbNocRouter_instance = new MOD_mkTbNocRouter(sim_hdl, "top", NULL);
  bk_get_or_define_clock(sim_hdl, "CLK");
  if (master)
  {
    bk_alter_clock(sim_hdl, bk_get_clock_by_name(sim_hdl, "CLK"), CLK_LOW, false, 0llu, 5llu, 5llu);
    bk_use_default_reset(sim_hdl);
  }
  bk_set_clock_event_fn(sim_hdl,
			bk_get_clock_by_name(sim_hdl, "CLK"),
			schedule_posedge_CLK,
			NULL,
			(tEdgeDirection)(POSEDGE));
  (mkTbNocRouter_instance->INST_router.INST_inQ_0.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_inQ_1.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_inQ_2.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_inQ_3.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_inQ_4.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_outQ_0.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_outQ_1.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_outQ_2.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_outQ_3.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_outQ_4.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_pkt_dir.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_route_dir.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_routerLatency_injected.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_routerLatency_collected.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_start_wire.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_start_reg_2.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_abort.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_state_set_pw.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_state_overlap_pw.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_state_fired_1.set_clk_0)("CLK");
  (mkTbNocRouter_instance->set_clk_0)("CLK");
}
void MODEL_mkTbNocRouter::destroy_model()
{
  delete mkTbNocRouter_instance;
  mkTbNocRouter_instance = NULL;
}
void MODEL_mkTbNocRouter::reset_model(bool asserted)
{
  (mkTbNocRouter_instance->reset_RST_N)(asserted ? (tUInt8)0u : (tUInt8)1u);
}
void * MODEL_mkTbNocRouter::get_instance()
{
  return mkTbNocRouter_instance;
}

